  // Round-robin service chooses one eligible read or write request.
  always_comb begin : p_com_axi_issue
    w_issue_rd = 1'b0;
    w_issue_wr = 1'b0;
    casez ({(w_rd_cmd_r_valid & w_rd_rsp_w_ready),
             (w_wr_cmd_r_valid & w_wr_rsp_w_ready), reg_axi_rr_rd})
      3'b111: w_issue_rd = 1'b1;
      3'b110: w_issue_wr = 1'b1;
      3'b10?: w_issue_rd = 1'b1;
      3'b01?: w_issue_wr = 1'b1;
      default: begin
        w_issue_rd = 1'b0;
        w_issue_wr = 1'b0;
      end
    endcase
  end
  // Consume the selected command and recover its address and write payload.
  assign w_rd_cmd_r_ready = w_issue_rd;
  assign w_wr_cmd_r_ready = w_issue_wr;
  assign w_issue_addr = w_issue_rd ? w_rd_cmd_r_data : w_wr_cmd_r_data[67:36];
  assign w_issue_wdata = w_wr_cmd_r_data[35:4];
  assign w_issue_wstrb = w_wr_cmd_r_data[3:0];
  assign w_addr = w_issue_addr;
  assign w_wdata = w_issue_wdata;
  assign w_wstrb = w_issue_wstrb;
  assign w_issue_resp = (w_issue_addr[1:0] != 2'b00) ? 2'(LPARA_AXI_RESP_SLVERR)
                      : (~w_addr_mapped ? 2'(LPARA_AXI_RESP_DECERR)
                      : ((w_issue_wr & (PARA_WSTRB_MODE == 32'd1) & ~(&w_issue_wstrb))
                         ? 2'(LPARA_AXI_RESP_SLVERR) : 2'(LPARA_AXI_RESP_OKAY)));
  // Generate CSR side effects only for successful decoded accesses.
  assign w_rd_en = w_issue_rd & (w_issue_resp == 2'(LPARA_AXI_RESP_OKAY));
  assign w_wr_en = w_issue_wr & (w_issue_resp == 2'(LPARA_AXI_RESP_OKAY));
  assign w_rd_rsp_w_valid = w_issue_rd;
  assign w_rd_rsp_w_data = {w_issue_resp, (w_rd_en ? w_rdata_nxt : '0)};
  assign w_wr_rsp_w_valid = w_issue_wr;
  assign w_wr_rsp_w_data = w_issue_resp;
  assign w_axi_rr_rd_nxt = w_issue_rd ? 1'b0 : (w_issue_wr ? 1'b1 : reg_axi_rr_rd);
  // Advance the read/write priority after each accepted CSR operation.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_axi_rr
    if (!w_rst_n_reg)
      reg_axi_rr_rd <= 1'b1;
    else
      reg_axi_rr_rd <= w_axi_rr_rd_nxt;
  end
  // Expand each byte strobe into the corresponding data mask.
  generate
    for (genvar gen_lane = 0; gen_lane < LPARA_STRB_W; gen_lane++) begin : gen_axi_wmask
      // Expand this byte lane's write strobe into its data-bit mask.
      assign w_wmask[(gen_lane * LPARA_AXI_BYTE_W) +: LPARA_AXI_BYTE_W] = {LPARA_AXI_BYTE_W{w_wstrb[gen_lane]}};
    end
  endgenerate

  // Per-register write/read address enables.
  assign w_we_pmu_ctrl = w_wr_en & (w_addr == LPARA_PMU_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_irq_en = w_wr_en & (w_addr == LPARA_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_irq_raw = w_wr_en & (w_addr == LPARA_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]);
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_PMU_EVT_COUNT) && (gen_idx < LPARA_PMU_EVT_MAX_COUNT); gen_idx++) begin : gen_pmu_evt_we_decode
    // Decode the software write for this parameterized register index.
    assign w_we_pmu_evt[gen_idx] = w_wr_en & (32'(w_addr) == (LPARA_PMU_EVT_BASE_OFFSET + (gen_idx * LPARA_PMU_EVT_OFFSET_STRIDE)));
  end
  endgenerate

  // pmu_ctrl_snapshot_req next value (wo): hardware clear overrides software writes.
  assign w_pmu_ctrl_snapshot_req_nxt = i_hw_clr_pmu_ctrl_snapshot_req ? '0
               : (w_we_pmu_ctrl & (|w_wmask[0])) ? ((w_wdata[0] & w_wmask[0]) | (reg_pmu_ctrl_snapshot_req & ~w_wmask[0]))
               : reg_pmu_ctrl_snapshot_req;

  // pmu_ctrl_snapshot_done next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_pmu_ctrl_snapshot_done_nxt = (i_hw_we_pmu_ctrl_snapshot_done) ? i_hw_wdata_pmu_snap_done
                          : ((w_we_pmu_ctrl & (|w_wmask[1])) ? (reg_pmu_ctrl_snapshot_done & ~(w_wdata[1] & w_wmask[1])) : reg_pmu_ctrl_snapshot_done);

  // Register pmu_ctrl: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_pmu_ctrl
    if (!w_rst_n_reg) begin
      reg_pmu_ctrl_snapshot_req <= 1'h0;
      reg_pmu_ctrl_snapshot_done <= 1'h0;
    end else begin
      reg_pmu_ctrl_snapshot_req <= w_pmu_ctrl_snapshot_req_nxt;
      reg_pmu_ctrl_snapshot_done <= w_pmu_ctrl_snapshot_done_nxt;
    end
  end

  // Register pmu_ctrl: output ports follow the flops.
  assign o_pmu_ctrl_snapshot_req = reg_pmu_ctrl_snapshot_req;
  assign o_pmu_ctrl_snapshot_done = reg_pmu_ctrl_snapshot_done;

  // Register pmu_ctrl: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_pmu_ctrl_value
    w_pmu_ctrl_value = '0;
    w_pmu_ctrl_value[1] = reg_pmu_ctrl_snapshot_done;
  end

  // irq_en_overflow_enable next value (rw): update only byte lanes selected by the bus strobe.
  assign w_irq_en_overflow_en_nxt = (w_we_irq_en & (|w_wmask[31:0])) ? ((w_wdata[31:0] & w_wmask[31:0]) | (reg_irq_en_overflow_en & ~w_wmask[31:0])) : reg_irq_en_overflow_en;

  // Register irq_en: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_irq_en
    if (!w_rst_n_reg) begin
      reg_irq_en_overflow_en <= 32'h0;
    end else begin
      reg_irq_en_overflow_en <= w_irq_en_overflow_en_nxt;
    end
  end

  // Register irq_en: output ports follow the flops.
  assign o_irq_en_overflow_en = reg_irq_en_overflow_en;

  // Register irq_en: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_irq_en_value
    w_irq_en_value = '0;
    w_irq_en_value[31:0] = reg_irq_en_overflow_en;
  end

  // irq_raw_overflow next value (w1c): hardware update wins; selected written 1 bits clear.
  assign w_irq_raw_overflow_nxt = (i_hw_we_irq_raw_overflow) ? i_hw_wdata_irq_raw_overflow
                          : ((w_we_irq_raw & (|w_wmask[31:0])) ? (reg_irq_raw_overflow & ~(w_wdata[31:0] & w_wmask[31:0])) : reg_irq_raw_overflow);

  // Register irq_raw: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_irq_raw
    if (!w_rst_n_reg) begin
      reg_irq_raw_overflow <= 32'h0;
    end else begin
      reg_irq_raw_overflow <= w_irq_raw_overflow_nxt;
    end
  end

  // Register irq_raw: output ports follow the flops.
  assign o_irq_raw_overflow = reg_irq_raw_overflow;

  // Register irq_raw: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_irq_raw_value
    w_irq_raw_value = '0;
    w_irq_raw_value[31:0] = reg_irq_raw_overflow;
  end

  // Register irq_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_irq_sts_value
    w_irq_sts_value = '0;
    w_irq_sts_value[31:0] = i_irq_sts_overflow_pending;
  end

  // Parameterized register group pmu_evt: indexed field updates and per-copy storage.
  generate
    for (genvar gen_idx = 0; (gen_idx < PARA_PMU_EVT_COUNT) && (gen_idx < LPARA_PMU_EVT_MAX_COUNT); gen_idx++) begin : gen_pmu_evt
    // Merge byte-strobed software data with the current PMU field state.
    assign w_pmu_evt_event_id_nxt[gen_idx] = (w_we_pmu_evt[gen_idx] & (|w_wmask[15:0])) ? ((w_wdata[15:0] & w_wmask[15:0]) | (reg_pmu_evt_event_id[gen_idx] & ~w_wmask[15:0])) : reg_pmu_evt_event_id[gen_idx];
    assign w_pmu_evt_scope_nxt[gen_idx] = (w_we_pmu_evt[gen_idx] & (|w_wmask[18:16])) ? ((w_wdata[18:16] & w_wmask[18:16]) | (reg_pmu_evt_scope[gen_idx] & ~w_wmask[18:16])) : reg_pmu_evt_scope[gen_idx];
    assign w_pmu_evt_en_nxt[gen_idx] = (w_we_pmu_evt[gen_idx] & (|w_wmask[19])) ? ((w_wdata[19] & w_wmask[19]) | (reg_pmu_evt_en[gen_idx] & ~w_wmask[19])) : reg_pmu_evt_en[gen_idx];
    // Pack this PMU register group's fields into the read-data vector.
    always_comb begin : p_com_pmu_evt_value
      w_pmu_evt_value[gen_idx] = '0;
      w_pmu_evt_value[gen_idx][15:0] = reg_pmu_evt_event_id[gen_idx];
      w_pmu_evt_value[gen_idx][18:16] = reg_pmu_evt_scope[gen_idx];
      w_pmu_evt_value[gen_idx][19] = reg_pmu_evt_en[gen_idx];
    end
    // One state bank per generated register index.
    always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_pmu_evt
      if (!w_rst_n_reg) begin
        reg_pmu_evt_event_id[gen_idx] <= 16'h0;
        reg_pmu_evt_scope[gen_idx] <= 3'h0;
        reg_pmu_evt_en[gen_idx] <= 1'h0;
      end else begin
        reg_pmu_evt_event_id[gen_idx] <= w_pmu_evt_event_id_nxt[gen_idx];
        reg_pmu_evt_scope[gen_idx] <= w_pmu_evt_scope_nxt[gen_idx];
        reg_pmu_evt_en[gen_idx] <= w_pmu_evt_en_nxt[gen_idx];
      end
    end
    end
  endgenerate
  // Expose the configured PMU event selector fields to the cluster.
  assign o_pmu_evt_event_id = reg_pmu_evt_event_id;
  assign o_pmu_evt_scope = reg_pmu_evt_scope;
  assign o_pmu_evt_en = reg_pmu_evt_en;

  // Parameterized register group pmu_count_lo: indexed field updates and per-copy storage.
  generate
    for (genvar gen_idx = 0; (gen_idx < PARA_PMU_COUNT_LO_COUNT) && (gen_idx < LPARA_PMU_COUNT_LO_MAX_COUNT); gen_idx++) begin : gen_pmu_count_lo
    // Pack this PMU register group's fields into the read-data vector.
    always_comb begin : p_com_pmu_count_lo_value
      w_pmu_count_lo_value[gen_idx] = '0;
      w_pmu_count_lo_value[gen_idx][31:0] = i_pmu_count_lo_value[gen_idx];
    end
    end
  endgenerate

  // Parameterized register group pmu_count_hi: indexed field updates and per-copy storage.
  generate
    for (genvar gen_idx = 0; (gen_idx < PARA_PMU_COUNT_HI_COUNT) && (gen_idx < LPARA_PMU_COUNT_HI_MAX_COUNT); gen_idx++) begin : gen_pmu_count_hi
    // Pack this PMU register group's fields into the read-data vector.
    always_comb begin : p_com_pmu_count_hi_value
      w_pmu_count_hi_value[gen_idx] = '0;
      w_pmu_count_hi_value[gen_idx][31:0] = i_pmu_count_hi_value[gen_idx];
    end
    end
  endgenerate

  // Unmapped register addresses return zero and generate DECERR.
  // Decode one parameterized register range without expanding guarded case items.
  function automatic logic [32:0] w_decode_pmu_evt(input logic [LPARA_ADDR_W-1:0] i_addr);
    logic [31:0] w_idx;
    begin
      w_decode_pmu_evt = '0;
      w_idx = '0;
      if ((32'(i_addr) >= LPARA_PMU_EVT_BASE_OFFSET)
          & (32'(i_addr) < (LPARA_PMU_EVT_BASE_OFFSET + (PARA_PMU_EVT_COUNT * LPARA_PMU_EVT_OFFSET_STRIDE)))
          & (((32'(i_addr) - LPARA_PMU_EVT_BASE_OFFSET) % LPARA_PMU_EVT_OFFSET_STRIDE) == 32'd0)) begin
        w_idx = (32'(i_addr) - LPARA_PMU_EVT_BASE_OFFSET) / LPARA_PMU_EVT_OFFSET_STRIDE;
        w_decode_pmu_evt = {1'b1, w_pmu_evt_value[w_idx]};
      end
    end
  endfunction
  // Decode the parameterized address range and retain valid/data fields.
  assign w_pmu_evt_decode = w_decode_pmu_evt(w_addr);
  assign w_pmu_evt_decode_valid = w_pmu_evt_decode[32];
  assign w_pmu_evt_decode_data = w_pmu_evt_decode[31:0];
  // Decode one parameterized register range without expanding guarded case items.
  function automatic logic [32:0] w_decode_pmu_count_lo(input logic [LPARA_ADDR_W-1:0] i_addr);
    logic [31:0] w_idx;
    begin
      w_decode_pmu_count_lo = '0;
      w_idx = '0;
      if ((32'(i_addr) >= LPARA_PMU_COUNT_LO_BASE_OFFSET)
          & (32'(i_addr) < (LPARA_PMU_COUNT_LO_BASE_OFFSET + (PARA_PMU_COUNT_LO_COUNT * LPARA_PMU_CNT_LO_STRIDE)))
          & (((32'(i_addr) - LPARA_PMU_COUNT_LO_BASE_OFFSET) % LPARA_PMU_CNT_LO_STRIDE) == 32'd0)) begin
        w_idx = (32'(i_addr) - LPARA_PMU_COUNT_LO_BASE_OFFSET) / LPARA_PMU_CNT_LO_STRIDE;
        w_decode_pmu_count_lo = {1'b1, w_pmu_count_lo_value[w_idx]};
      end
    end
  endfunction
  // Decode the parameterized address range and retain valid/data fields.
  assign w_pmu_count_lo_decode = w_decode_pmu_count_lo(w_addr);
  assign w_pmu_count_lo_decode_valid = w_pmu_count_lo_decode[32];
  assign w_pmu_count_lo_decode_data = w_pmu_count_lo_decode[31:0];
  // Decode one parameterized register range without expanding guarded case items.
  function automatic logic [32:0] w_decode_pmu_count_hi(input logic [LPARA_ADDR_W-1:0] i_addr);
    logic [31:0] w_idx;
    begin
      w_decode_pmu_count_hi = '0;
      w_idx = '0;
      if ((32'(i_addr) >= LPARA_PMU_COUNT_HI_BASE_OFFSET)
          & (32'(i_addr) < (LPARA_PMU_COUNT_HI_BASE_OFFSET + (PARA_PMU_COUNT_HI_COUNT * LPARA_PMU_CNT_HI_STRIDE)))
          & (((32'(i_addr) - LPARA_PMU_COUNT_HI_BASE_OFFSET) % LPARA_PMU_CNT_HI_STRIDE) == 32'd0)) begin
        w_idx = (32'(i_addr) - LPARA_PMU_COUNT_HI_BASE_OFFSET) / LPARA_PMU_CNT_HI_STRIDE;
        w_decode_pmu_count_hi = {1'b1, w_pmu_count_hi_value[w_idx]};
      end
    end
  endfunction
  // Decode the parameterized address range and retain valid/data fields.
  assign w_pmu_count_hi_decode = w_decode_pmu_count_hi(w_addr);
  assign w_pmu_count_hi_decode_valid = w_pmu_count_hi_decode[32];
  assign w_pmu_count_hi_decode_data = w_pmu_count_hi_decode[31:0];
  // Select the CSR read value and mapped-address status.
  always_comb begin : p_com_reg_rd_decode
    w_rdata_nxt = '0;
    w_addr_mapped = 1'b0;
    case (32'(w_addr))
      LPARA_PMU_CTRL_OFFSET: begin w_rdata_nxt = w_pmu_ctrl_value; w_addr_mapped = 1'b1; end
      LPARA_IRQ_EN_OFFSET: begin w_rdata_nxt = w_irq_en_value; w_addr_mapped = 1'b1; end
      LPARA_IRQ_RAW_OFFSET: begin w_rdata_nxt = w_irq_raw_value; w_addr_mapped = 1'b1; end
      LPARA_IRQ_STS_OFFSET: begin w_rdata_nxt = w_irq_sts_value; w_addr_mapped = 1'b1; end
      default: begin w_rdata_nxt = '0; w_addr_mapped = 1'b0; end
    endcase
    // Apply the matching parameterized register-bank result, if any.
    if (w_pmu_evt_decode_valid) begin
      w_rdata_nxt = w_pmu_evt_decode_data;
      w_addr_mapped = 1'b1;
    end
    // Apply the matching parameterized register-bank result, if any.
    if (w_pmu_count_lo_decode_valid) begin
      w_rdata_nxt = w_pmu_count_lo_decode_data;
      w_addr_mapped = 1'b1;
    end
    // Apply the matching parameterized register-bank result, if any.
    if (w_pmu_count_hi_decode_valid) begin
      w_rdata_nxt = w_pmu_count_hi_decode_data;
      w_addr_mapped = 1'b1;
    end
  end

endmodule
